begin;
do $test$
declare u uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();shop uuid;settings jsonb:='{"businessName":"Settings sections QA","address":"","phones":"","email":"","website":"","socials":"","logo":"","logoVariants":{"complete":{"light":"","dark":""},"stacked":{"light":"","dark":""},"horizontal":{"light":"","dark":""},"wordmark":{"light":"","dark":""},"icon":{"light":"","dark":""}},"logoUsage":{"sidebar":"horizontal","documents":"complete","favicon":"icon"},"primary":"#124b40","accent":"#d9a126","theme":"system","backgrounds":{"light":{"canvas":"","surface":"","surfaceAlt":""},"dark":{"canvas":"","surface":"","surfaceAlt":""}},"options":{"paymentMethods":[{"label":"Cash","kind":"Cash","enabled":true},{"label":"POS","kind":"POS","enabled":true},{"label":"Transfer","kind":"Transfer","enabled":true}],"expenseCategories":["Materials","Electricity","Fuel","Rent","Wages","Maintenance","Delivery","Outsourcing","Internet / phone","Other"],"jobSources":["In shop / USB","Shop network","WhatsApp","Email","Other"],"stockReasons":["Restocking","Stock Count Correction","Returned Stock","Damaged Stock"],"materialUnits":["sheet","piece","metre","square metre","roll","kilogram","litre"],"jobStages":["Added","In Queue","Printing","Completed","Collected"]},"corrections":{"recentDays":7},"security":{"autoLockMinutes":0,"syncMinutes":2},"jobs":{"defaultDuration":{"value":0,"unit":"days"},"paymentPrefill":"suggested","descriptionMode":"required","stockBelowZero":"allow"},"pricing":{"enabled":false,"maxTemplates":100,"auditRanks":[2,3],"templates":[]},"periods":{"dashboard":"month","reports":"month","pointOfService":"30days","jobs":"all","payments":"all","expenses":"all","stockHistory":"all","mySales":"today"},"discounts":{"maxPercent":{"1":0,"2":20,"3":100}},"terms":{"preset":"print","job":"job","jobs":"jobs","service":"service","services":"services","material":"material","materials":"materials","stages":{"Added":"Added","Completed":"Completed","Collected":"Collected"}},"pageAccess":{"1":["Point of Service","Quotations","Pricing Templates","My Sales","Print Settings","My Account"],"2":["Dashboard","Reports","Point of Service","Quotations","Pricing Templates","My Sales","Jobs","Customers","Payment Reminders","Payments","Expenses","Payees","Accounts","Materials","Services","Edit Products","Stock History","Print Settings","Users","My Account","Conflict Inbox","Sale Adjustments","Material Waste","Business Settings"],"3":["Dashboard","Reports","Point of Service","Quotations","Pricing Templates","My Sales","Jobs","Customers","Payment Reminders","Payments","Expenses","Payees","Accounts","Materials","Services","Edit Products","Stock History","Print Settings","Users","My Account","Conflict Inbox","Sale Adjustments","Material Waste","Business Settings"]},"pageAccessVersion":3,"settingsTabs":{"2":["Words"],"3":["Default time frames"]},"settingsTabsVersion":2,"receipt":{"showLogo":true,"showBusinessName":true,"showAddress":true,"showContacts":true,"footer":"Thank you for your business.","logoLayout":"","logoPosition":"right","headline":"description","showSubline":true,"showJobId":true,"showQuantity":true,"showSize":true,"showSource":true,"showDueDate":true,"showPaidBefore":true,"showPaidNow":true,"showItemBalance":true,"showCustomerPhone":true,"showCashier":true,"showPaymentDate":true,"showPaymentMethod":true,"showWalletMovements":true,"showAccountBalances":true,"showNote":true},"receiptPage":{"logoLayout":"","logoPosition":"right","showLogo":true,"showBusinessName":true,"showAddress":true,"showContacts":true,"footer":"Thank you for your business.","headline":"description","showSubline":true,"showJobId":true,"showQuantity":true,"showSize":true,"showSource":true,"showDueDate":true,"showPaidBefore":true,"showPaidNow":true,"showItemBalance":true,"showCustomerPhone":true,"showCashier":true,"showPaymentDate":true,"showPaymentMethod":true,"showWalletMovements":true,"showAccountBalances":true,"showNote":true},"documents":{"watermark":false,"watermarkLogoLayout":"","invoiceTerms":"","quotationTerms":"","showTermsOnRoll":false},"poweredBy":{"text":"","receipts":false,"pages":false,"reports":false,"shares":false},"branches":[],"branchAccess":{},"branchPricing":"shared"}'::jsonb;candidate jsonb;result jsonb;ver int:=0;saved_periods jsonb;
begin
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data,created_at)values(u,'settings-sections@example.invalid',now(),'{}',now()),(dev,'staff-developer-sections@staff.printshopledger.invalid',now(),'{}',now());
shop:=(public.complete_business_registration(u,dev,'Settings sections QA','Tester',repeat('c',64),'https://print-shop-ledger.vercel.app/#developer_activation='||repeat('c',64))->>'shopId')::uuid;
perform set_config('request.jwt.claim.sub',u::text,true);update public.shop_members set access_level=4,rank=4,role='developer'where shop_id=shop and user_id=u;
select coalesce((select version from public.business_settings where shop_id=shop),0)into ver;
result:=public.save_business_settings(shop,ver,settings);settings:=result->'settings';ver:=(result->>'version')::int;saved_periods:=settings->'periods';
update public.shop_members set access_level=2,rank=2,role='admin'where shop_id=shop and user_id=u;
candidate:=jsonb_set(settings,'{terms,job}','"purchase"'::jsonb);candidate:=jsonb_set(candidate,'{terms,preset}','"custom"'::jsonb);candidate:=jsonb_set(candidate,'{periods,dashboard}','"today"'::jsonb);
result:=public.save_business_settings(shop,ver,candidate);settings:=result->'settings';ver:=(result->>'version')::int;
if settings->'periods' is distinct from saved_periods or settings->'terms'->>'job'<>'purchase' then raise exception 'Words section permissions failed';end if;
update public.shop_members set access_level=3,rank=3,role='manager'where shop_id=shop and user_id=u;
candidate:=jsonb_set(settings,'{periods,dashboard}','"week"'::jsonb);candidate:=jsonb_set(candidate,'{terms,job}','"forbidden"'::jsonb);
result:=public.save_business_settings(shop,ver,candidate);settings:=result->'settings';ver:=(result->>'version')::int;
if settings->'terms'->>'job'<>'purchase' or settings->'periods'->>'dashboard'<>'week' then raise exception 'Time-frame section permissions failed';end if;
update public.shop_members set access_level=4,rank=4,role='developer'where shop_id=shop and user_id=u;
settings:=settings||'{"settingsTabsVersion":1,"settingsTabs":{"2":["Jobs & payments"],"3":[]}}'::jsonb;
result:=public.save_business_settings(shop,ver,settings);settings:=result->'settings';ver:=(result->>'version')::int;
update public.shop_members set access_level=2,rank=2,role='admin'where shop_id=shop and user_id=u;
candidate:=jsonb_set(settings,'{terms,job}','"legacy order"'::jsonb);candidate:=jsonb_set(candidate,'{periods,dashboard}','"today"'::jsonb);
result:=public.save_business_settings(shop,ver,candidate);
if result->'settings'->'terms'->>'job'<>'legacy order' or result->'settings'->'periods'->>'dashboard'<>'today' then raise exception 'Legacy settings access was not preserved';end if;
end $test$;
rollback;
